Set<String> a = new TreeSet<>(Set.of("Rossi", "Bianchi", "Verdi"));
Set<String> b = Set.of("Verdi", "Neri", "Rossi");
a.retainAll(b);
System.out.println(a);

List<String> cities = List.of("Roma", "Milano", "Roma", "Napoli", "Roma", "Milano");
Map<String, Long> count = cities.stream()
        .collect(Collectors.groupingBy(city -> city, TreeMap::new, Collectors.counting()));
System.out.println(count);

int[][] orders = {{1, 10}, {2, 10}, {3, 20}, {4, 30}};
int[] customers = {10, 20, 40};
int rows = 0;
for (int[] order : orders) {
    for (int customer : customers) {
        if (order[1] == customer) {
            rows++;
        }
    }
}
System.out.println(rows);
